import json, os, re, struct, sys
prefix=sys.argv[1]
rows=[]
with open(\"ortg.tsv\",\"r\",encoding=\"utf-8\") as f:
    for line in f:
        cols=line.rstrip(\"\\n\").split(\"\\t\")
        if len(cols)>=7 and cols[0].startswith(prefix) and cols[2]==\"0\" and cols[6]==\"\":
            rows.append(cols[0])
def clean(s, limit=180):
    s=re.sub(r\"<["'^>]+>"," ",s)
    s=re.sub(r"!?'"\\[["'^'"\\]]*\\]\\(["'^)]*'"\\)\",\" \",s)
    s=re.sub(r\"[#*_]+\",\" \",s)
    s=re.sub(r\"\\{["'^{}]*'"\\}\",\" \",s)
    s=\" \".join(s.replace(\"|\",\"/\").split())
    return s[:limit].rstrip(\" ,;:-\")
def size_tag(data):
    n=data.count(b\"\\n\")+1
    return \"L\" if n>400 else \"M\" if n>=200 else \"S\" if n>=100 else \"T\"
def lang_for(p):
    a=p.split(\"/\")
    return a[1] if len(a)>2 and a[0]==\"docs\" else \"project\"
def topic_for(p):
    parts=p.split(\"/\")
    stem=os.path.splitext(parts[-1])[0].replace(\"-\",\" \")
    if \"img\" in parts:
        i=parts.index(\"img\")
        topic=\" / \".join(x.replace(\"-\",\" \") for x in parts[i+1:-1])
        return topic or stem
    return stem
def outline(p):
    data=open(p,\"rb\").read()
    name=os.path.basename(p)
    ext=os.path.splitext(name)[1].lower()
    scale=size_tag(data)
    lang=lang_for(p)
    imp=\"5\"
    role=\"\"
    constraints=\"-\"
    api=\"-\"
    uses=\"-\"
    if ext==\".md\":
        text=data.decode(\"utf-8\",\"replace\")
        lines=text.splitlines()
        title=\"\"
        for s in lines[:100]:
            m=re.match(r\""'^#'"\\s+(.+?)\\s*"'$",s)
            if m:
                title=clean(m.group(1),100); break
        if not title:
            for s in lines[:50]:
                m=re.match(r"''^title:'"\\s*[\\\"'\"'\"']?(.+?)[\\\"'\"'\"']?\\s*"'$",s,re.I)
                if m:
                    title=clean(m.group(1),100); break
        if not title:
            title=topic_for(p)
        heads=[]
        for s in lines:
            m=re.match(r"''^##+'"\\s+(.+?)\\s*"'$",s)
            if m:
                h=clean(m.group(1),70)
                if h and h not in heads: heads.append(h)
            if len(heads)>=4: break
        role=f"提供{lang}文档页《{title}》"
        if heads: role+="，涵盖"+"、".join(heads)
        else:
            para=""
            for s in lines:
                c=clean(s,160)
                if len(c)>35 and not s.lstrip().startswith(("---","{%","<!--","'"\\x60\\x60\\x60\",\""'!!!","???")):
                    para=c; break
            if para and para.lower()!=title.lower(): role+="，说明"+para
        role=role[:280]
        explicit=[]
        for s in lines:
            st=s.strip()
            if re.search(r"'"\\b(must|should|do not|don'\"'\"'t|never|required|important|warning|note)\\b\",st,re.I) or st.startswith((\""'!!!","???")):
                c=clean(st,150)
                if len(c)>12 and c not in explicit: explicit.append(c)
            if len(explicit)>=2: break
        if explicit: constraints="；".join(explicit)[:360]
        if p=="docs/missing-translation.md": imp="7"
    elif ext in (".png",".jpg",".jpeg"):
        w=h=None
        if ext==".png" and data[:8]==b"'"\\x89PNG\\r\\n\\x1a\\n\" and len(data)>=24:
            w,h=struct.unpack(\">II\",data[16:24])
        dims=f\"{w}×{h}\" if w and h else \"位图\"
        role=f\"为{topic_for(p)}文档提供{name} {dims}图像资产\"
        constraints=\"保持文档引用路径与图像含义稳定\"
        imp=\"3\"
    elif ext==\".svg\":
        text=data.decode(\"utf-8\",\"replace\")
        titlem=re.search(r\"<title["'^>]*>(.*?)</title>",text,re.S|re.I)
        viewm=re.search(r"viewBox=['"\\\"'\"'\"'](["'^'"\\\"'\"'\"']+)\",text,re.I)
        desc=clean(titlem.group(1),100) if titlem else topic_for(p)
        role=f\"为{topic_for(p)}文档提供{desc}矢量图\"
        constraints=(\"保持文档引用路径\"+(f\"及 viewBox {clean(viewm.group(1),60)}\" if viewm else \"\")+\"稳定\")
        imp=\"3\"
    elif ext in (\".yml\",\".yaml\"):
        text=data.decode(\"utf-8\",\"replace\")
        keys=[]
        for s in text.splitlines():
            m=re.match(r\""'^([A-Za-z_]['"\\w-]*):\",s)
            if m and m.group(1) not in keys: keys.append(m.group(1))
            if len(keys)>=8: break
        if name.startswith(\"mkdocs\"):
            role=f\"配置{lang}文档站的导航、主题、插件、Markdown 扩展与构建选项\"
        elif \"/data/\" in p:
            role=f\"维护英文文档生成使用的{name}结构化数据\"
        else:
            role=f\"维护文档系统的{name}配置数据\"
        if keys: constraints=\"顶层数据契约包含 \"+\", \".join(keys)
    elif ext==\".js\":
        text=data.decode(\"utf-8\",\"replace\")
        funcs=re.findall(r\"(?:function\\s+|class\\s+)([A-Za-z_"'$]['"\\w"'$]*)",text)
        role=f"实现文档站{name}浏览器交互"+(("，核心入口 "+", ".join(dict.fromkeys(funcs[:5]))) if funcs else "")
        api=", ".join(dict.fromkeys(funcs[:8])) or "-"
    elif ext==".css":
        text=data.decode("utf-8","replace")
        sels=[]
        for m in re.finditer(r"([''^{}]+)'"\\{\",text):
            s=clean(m.group(1),60)
            if s and not s.startswith(\"@\") and s not in sels: sels.append(s)
            if len(sels)>=5: break
        role=f\"定义文档站{name}样式\"+((\"，覆盖 \"+\", \".join(sels)) if sels else \"\")
    elif ext in (\".html\",\".htm\"):
        text=data.decode(\"utf-8\",\"replace\")
        blocks=re.findall(r\"\\{%\\s*(?:block|macro)\\s+(["'^'"\\s%]+)\",text)
        role=f\"提供文档站{name}模板覆盖\"+((\"，定义 \"+\", \".join(blocks[:6])) if blocks else \"\")
        api=\", \".join(blocks[:8]) or \"-\"
    else:
        role=f\"提供{lang}文档系统的{name}资源\"
    role=clean(role,300) or f\"维护文档资源 {name}\"
    constraints=clean(constraints,450) if constraints"'!="-" else "-"
    return f"{name}[{imp} O G {scale}]: Role:{role} | Uses:{uses} | API:{api} | Constraints:{constraints}"
print(json.dumps([[p,outline(p)] for p in rows],ensure_ascii=False))
'"' 'docs/language_names.yml'"

